import json
import itertools

def solve_puzzle():
    houses = [1, 2, 3, 4, 5]

    names = ['Alice', 'Bob', 'Arnold', 'Eric', 'Peter']
    vacations = ['cruise', 'city', 'camping', 'beach', 'mountain']
    children = ['Bella', 'Samantha', 'Fred', 'Meredith', 'Timothy']
    nationalities = ['dane', 'norwegian', 'brit', 'german', 'swede']

    solutions = []

    # Helper to get position
    def pos(arr, val):
        return arr.index(val)

    for nat in itertools.permutations(nationalities):
        # Clue 12: The Dane is in the fifth house.
        if nat[4] != 'dane':
            continue
        # Clue 9: The Swedish person is somewhere to the right of the Norwegian.
        if pos(nat, 'swede') <= pos(nat, 'norwegian'):
            continue

        for child in itertools.permutations(children):
            # Clue 7: Meredith is in the fourth house.
            if child[3] != 'Meredith':
                continue
            # Clue 4: Bella is not in the second house.
            if child[1] == 'Bella':
                continue
            # Clue 2: The Swedish person's child is Bella.
            if child[pos(nat, 'swede')] != 'Bella':
                continue

            for vac in itertools.permutations(vacations):
                # Clue 6: Cruises in the first house.
                if vac[0] != 'cruise':
                    continue
                # Clue 13: Camping is not in the fifth house.
                if vac[4] == 'camping':
                    continue
                # Clue 3: Beach is directly left of Samantha.
                ok_beach_sam = False
                for i in range(4):
                    if vac[i] == 'beach' and child[i+1] == 'Samantha':
                        ok_beach_sam = True
                        break
                if not ok_beach_sam:
                    continue
                # Clue 10: One house between Fred and City.
                if abs(pos(child, 'Fred') - pos(vac, 'city')) != 2:
                    continue

                for name in itertools.permutations(names):
                    # Clue 5: Alice is the British person.
                    if nat[pos(name, 'Alice')] != 'brit':
                        continue
                    # Clue 1: The Norwegian is Peter.
                    if name[pos(nat, 'norwegian')] != 'Peter':
                        continue
                    # Clue 11: Bob enjoys camping.
                    if vac[pos(name, 'Bob')] != 'camping':
                        continue
                    # Clue 8: Eric is not in the fifth house.
                    if name[4] == 'Eric':
                        continue

                    # All constraints satisfied, record solution
                    solution = []
                    for i in range(5):
                        solution.append({
                            "House": str(i+1),
                            "Name": name[i],
                            "Vacation": vac[i],
                            "Children": child[i],
                            "Nationality": nat[i]
                        })
                    solutions.append(solution)

    # Expect a unique solution
    if not solutions:
        raise RuntimeError("No solution found.")
    # If multiple solutions exist, pick the first but ideally there should be one.
    result = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "Vacation", "Children", "Nationality"],
            "rows": [[row["House"], row["Name"], row["Vacation"], row["Children"], row["Nationality"]] for row in result]
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
